rn={ (r['SCOPE'],r['GRP_KEY']):r for r in slice('return-note',co)['summary'] }
T=[r for r in rows if r['SCOPE']=='TOTAL'][0]
alt=rn[('TOTAL','ALL')]['SALES_NET']; assert abs(T['DISP_VAL_L']*1e5 - alt) < 500
for tk,rk in [('EXTERNAL','EXTERNAL'),('BRANCH','BRANCH'),('INTERCOMPANY','INTERCOMPANY')]:
    p=[r for r in rows if r['SCOPE']=='PARTY' and r['GRP_KEY']==tk][0]
    assert abs(p['DISP_VAL_L']*1e5 - rn[('CLASS',rk)]['SALES_NET']) < 500
for s in ['NAMECLASS','PARTY','MONTH']:
    assert sum(r['DISP_DOCS'] for r in rows if r['SCOPE']==s) == T['DISP_DOCS']

det=slice('transporter',co)['detail']; fam={}
for r in det:
    f=fam.setdefault(r['FAM_KEY'],{'v':0.0,'d':0}); f['v']+=r['DISP_VAL_L']; f['d']+=r['DISP_DOCS']
for s in [r for r in rows if r['SCOPE']=='TRANSPORTER']:
    if s['GRP_KEY'] in fam:
        assert fam[s['GRP_KEY']]['d']==s['DISP_DOCS'] and abs(fam[s['GRP_KEY']]['v']-s['DISP_VAL_L'])<0.05
